package com.nextstep.web;
import com.nextstep.entity.*;import com.nextstep.repository.*;import com.nextstep.service.*;
import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") public class ProgressController {
 final QuizAttemptRepository quizzes;final CodingSubmissionRepository code;final ResumeReviewRepository resumes;final InterviewSessionRepository interviews;final LearningGoalRepository goals;final UserRepository users;final QuestionRepository questions;final CodingProblemRepository problems;final JsonService json;
 public ProgressController(QuizAttemptRepository quizzes,CodingSubmissionRepository code,ResumeReviewRepository resumes,InterviewSessionRepository interviews,LearningGoalRepository goals,UserRepository users,QuestionRepository questions,CodingProblemRepository problems,JsonService json){this.quizzes=quizzes;this.code=code;this.resumes=resumes;this.interviews=interviews;this.goals=goals;this.users=users;this.questions=questions;this.problems=problems;this.json=json;}
 record Goal(@NotBlank @Size(max=200) String title,@Pattern(regexp="\\d{4}-\\d{2}-\\d{2}") String dueDate){}
 @GetMapping("/goals") Object goals(){return goals.findByUserIdOrderByCreatedAtDesc(AuthController.uid());}
 @PostMapping("/goals") Object goal(@Valid @RequestBody Goal input){try{LocalDate.parse(input.dueDate());}catch(Exception e){throw Errors.bad("Choose a valid due date.");}var g=new LearningGoal();g.userId=AuthController.uid();g.title=input.title();g.dueDate=input.dueDate();g.completed=false;return goals.save(g);}
 @PostMapping("/goals/{id}/toggle") Object toggle(@PathVariable long id){var g=goals.findById(id).filter(x->x.userId==AuthController.uid()).orElseThrow(()->Errors.bad("Goal not found."));g.completed=!g.completed;return goals.save(g);}
 @GetMapping("/search") Object search(@RequestParam String q){if(q.length()<2||q.length()>100)return List.of();var result=new ArrayList<Map<String,Object>>();questions.findAll((r,query,b)->b.like(b.lower(r.get("prompt")),"%"+q.toLowerCase(Locale.ROOT)+"%"),org.springframework.data.domain.PageRequest.of(0,12)).forEach(x->result.add(Map.of("title",x.prompt,"topic",x.topic,"path","/"+x.kind)));problems.findAll().stream().filter(p->(p.title+" "+p.topic).toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))).limit(8).forEach(p->result.add(Map.of("title",p.title,"topic",p.topic,"path","/coding?problem="+p.id)));return result;}
 @GetMapping("/progress") Object progress(@RequestParam(defaultValue="30") int days,@RequestParam(defaultValue="UTC") String timezone){if(!List.of(1,7,30,3650).contains(days))throw Errors.bad("Invalid date range.");ZoneId zone;try{zone=ZoneId.of(timezone);}catch(Exception e){throw Errors.bad("Invalid timezone.");}long uid=AuthController.uid();var all=quizzes.findByUserIdOrderByCreatedAtDesc(uid).stream().filter(a->!a.status.equals("IN_PROGRESS")).toList();Instant from=LocalDate.now(zone).minusDays(days-1).atStartOfDay(zone).toInstant();var attempts=all.stream().filter(a->!a.createdAt.isBefore(from)).toList();var subs=code.findByUserIdOrderByCreatedAtDesc(uid);var revs=resumes.findByUserIdOrderByCreatedAtDesc(uid);var sessions=interviews.findByUserIdOrderByCreatedAtDesc(uid).stream().filter(s->s.status.equals("COMPLETED")).toList();int total=attempts.stream().mapToInt(a->a.total).sum(),correct=attempts.stream().mapToInt(a->a.score).sum();var topics=new TreeMap<String,int[]>();var unique=new HashSet<Long>();for(var a:all)json.read(a.details).forEach(n->unique.add(n.path("id").asLong()));for(var a:attempts)json.read(a.details).forEach(n->{var t=topics.computeIfAbsent(n.path("topic").asText(),k->new int[2]);t[1]++;if(n.path("correct").asBoolean())t[0]++;});var activity=new ArrayList<Map<String,Object>>();all.forEach(a->activity.add(event(a.kind+" quiz",a.kind,a.createdAt,a.score+"/"+a.total,a.total)));subs.forEach(s->activity.add(event("Coding submission", "coding",s.createdAt,s.status,0)));revs.forEach(r->activity.add(event("Resume review","resume",r.createdAt,r.score+"% completeness",0)));sessions.forEach(s->activity.add(event("Mock interview","interview",s.createdAt,s.score+"% practice score",0)));activity.sort((a,b)->((Instant)b.get("date")).compareTo((Instant)a.get("date")));var dates=new HashSet<LocalDate>();activity.forEach(e->dates.add(((Instant)e.get("date")).atZone(zone).toLocalDate()));LocalDate day=LocalDate.now(zone);if(!dates.contains(day))day=day.minusDays(1);int streak=0;while(dates.contains(day)){streak++;day=day.minusDays(1);}var timeline=new ArrayList<Map<String,Object>>();for(int i=Math.min(days,90)-1;i>=0;i--){var d=LocalDate.now(zone).minusDays(i);long count=activity.stream().filter(e->((Instant)e.get("date")).atZone(zone).toLocalDate().equals(d)).count();timeline.add(Map.of("date",d.toString(),"activities",count));}int today=all.stream().filter(a->a.createdAt.atZone(zone).toLocalDate().equals(LocalDate.now(zone))).mapToInt(a->a.total).sum();var m=new LinkedHashMap<String,Object>();m.put("attempted",total);m.put("correct",correct);m.put("accuracy",total==0?0:Math.round(correct*100f/total));m.put("codingSolved",subs.stream().filter(s->s.status.equals("ACCEPTED")&&!s.createdAt.isBefore(from)).map(s->s.problemId).distinct().count());m.put("codingAttempts",subs.stream().filter(s->!s.createdAt.isBefore(from)).count());m.put("resumeReviews",revs.stream().filter(r->!r.createdAt.isBefore(from)).count());m.put("interviews",sessions.stream().filter(s->!s.createdAt.isBefore(from)).count());m.put("seconds",attempts.stream().mapToInt(a->a.elapsedSeconds).sum()+sessions.stream().filter(s->!s.createdAt.isBefore(from)).mapToInt(s->s.elapsedSeconds).sum());m.put("coverage",questions.count()==0?0:Math.round(unique.size()*100f/questions.count()));m.put("streak",streak);m.put("todayQuestions",today);m.put("dailyGoal",users.findById(uid).orElseThrow().dailyGoal);m.put("timeline",timeline);m.put("topics",topics.entrySet().stream().map(e->Map.of("topic",e.getKey(),"correct",e.getValue()[0],"attempted",e.getValue()[1],"accuracy",Math.round(e.getValue()[0]*100f/e.getValue()[1]))).toList());m.put("activities",activity.stream().filter(e->!((Instant)e.get("date")).isBefore(from)).limit(100).toList());m.put("goals",goals.findByUserIdOrderByCreatedAtDesc(uid));return m;}
 Map<String,Object> event(String title,String kind,Instant date,String detail,int count){return Map.of("title",title,"kind",kind,"date",date,"detail",detail,"questions",count);}
}
